'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');
const { toObjects } = require('./src/rows');

function* chunks(text) {
  yield [text];
  yield text.split('');
  for (let split = 0; split <= text.length; split++) {
    yield [text.slice(0, split), text.slice(split)];
  }
  if (text.length <= 12) {
    for (let mask = 0; mask < 2 ** Math.max(0, text.length - 1); mask++) {
      const parts = [];
      let start = 0;
      for (let index = 1; index < text.length; index++) {
        if (mask & (1 << (index - 1))) {
          parts.push(text.slice(start, index));
          start = index;
        }
      }
      parts.push(text.slice(start));
      yield parts;
    }
  }
}

test('CSV values are invariant across chunk boundaries and empty pushes', () => {
  const cases = [
    ['', []], ['\uFEFF', []], ['\n', [['']]], ['\n\n', [[''], ['']]],
    ['\r\n', [['']]], ['\r\r\n\n', [[''], [''], ['']]],
    ['a\r\nb\rc\n', [['a'], ['b'], ['c']]],
    [',,', [['', '', '']]], ['a,', [['a', '']]],
    ['""', [['']]], ['""""', [['"']]],
    ['"a""b",c', [['a"b', 'c']]], ['a"b,c', [['a"b', 'c']]],
    ['"a\r\nb\rc\nd",e\r\n', [['a\r\nb\rc\nd', 'e']]],
    ['\uFEFFa,\uFEFFb\n\uFEFFc', [['a', '\uFEFFb'], ['\uFEFFc']]],
    ['\uFEFF\uFEFF', [['\uFEFF']]], ['😀,"😀"', [['😀', '😀']]],
    ['a;"b;c";', [['a', 'b;c', '']], { delimiter: ';' }],
    ['a\0b', [['a', 'b']], { delimiter: '\0' }],
    ['a\uD800b', [['a', 'b']], { delimiter: '\uD800' }],
    ['\uFEFFa\uFEFFb', [['a', 'b']], { delimiter: '\uFEFF' }],
  ];
  for (const [text, expected, options] of cases) {
    assert.deepEqual(parse(text, options), expected);
    for (const parts of chunks(text)) {
      const parser = createParser(options);
      const records = [];
      for (const part of parts) {
        assert.deepEqual(parser.push(''), []);
        records.push(...parser.push(part));
      }
      assert.deepEqual(parser.push(''), []);
      records.push(...parser.end());
      assert.deepEqual(records, expected, JSON.stringify(parts));
      assert.deepEqual(parser.end(), []);
      assert.throws(() => parser.push(''), Error);
    }
  }
});

test('completed records emit on CR immediately, without duplicates', () => {
  const parser = createParser({ header: true });
  assert.deepEqual(parser.push('a\r'), [['a']]);
  assert.deepEqual(parser.push(''), []);
  assert.deepEqual(parser.push('\nb\n\r'), [['b'], ['']]);
  assert.deepEqual(parser.push('\nc,'), []);
  assert.deepEqual(parser.end(), [['c', '']]);
  const left = createParser();
  const right = createParser();
  assert.deepEqual(left.push('"a'), []);
  assert.deepEqual(right.push('b\n'), [['b']]);
  assert.deepEqual(left.push('"\n'), [['a']]);
});

test('invalid delimiters, chunks, and ended lifecycle are rejected', () => {
  for (const delimiter of ['', 'ab', '😀', '"', '\r', '\n', null, 1, {}, []]) {
    assert.throws(() => createParser({ delimiter }), RangeError);
  }
  assert.deepEqual(parse('a,b', { delimiter: undefined }), [['a', 'b']]);
  const parser = createParser();
  for (const chunk of [undefined, null, 1, {}, [], Buffer.from('a')]) {
    assert.throws(() => parser.push(chunk), TypeError);
  }
  assert.deepEqual(parser.push('a\n'), [['a']]);
  assert.deepEqual(parser.end(), []);
  assert.deepEqual(parser.end(), []);
  assert.throws(() => parser.push('a'), Error);
});

test('syntax errors report physical lines through quoted and split newlines', () => {
  const cases = [
    ['"a"x', 1, false], ['"a" ', 1, false], ['x\r\n"a"x', 2, false],
    ['"a\r\nb\rc\nd"x', 4, false], ['"a"\r\n"b"\t', 2, false],
    ['"', 1, true], ['"a\r\n', 2, true], ['"a\rb\nc\r\n', 4, true],
    ['"a""', 1, true],
  ];
  for (const [text, line, atEnd] of cases) {
    for (const parts of chunks(text)) {
      const parser = createParser();
      const expected = error => error instanceof SyntaxError &&
        new RegExp(`\\bline ${line}\\b`).test(error.message);
      if (atEnd) {
        for (const part of parts) parser.push(part);
        assert.throws(() => parser.end(), expected);
      } else {
        assert.throws(() => {
          for (const part of parts) parser.push(part);
        }, expected);
      }
    }
  }
});

test('header conversion retains duplicate, padding and special-key contracts', () => {
  const result = parse('x,x,x_2,x,__proto__,constructor,toString\na,b,c,d,e,f,g\nshort', { header: true });
  assert.deepEqual(Object.keys(result[0]), ['x', 'x_2', 'x_2_2', 'x_3', '__proto__', 'constructor', 'toString']);
  assert.deepEqual(Object.values(result[0]), ['a', 'b', 'c', 'd', 'e', 'f', 'g']);
  assert.deepEqual(Object.values(result[1]), ['short', '', '', '', '', '', '']);
  assert.equal(Object.getPrototypeOf(result[0]), Object.prototype);
  for (const key of ['__proto__', 'constructor', 'toString']) {
    assert.deepEqual(Object.getOwnPropertyDescriptor(result[0], key), {
      value: result[0][key], enumerable: true, configurable: true, writable: true,
    });
  }
  assert.deepEqual(parse('', { header: true }), []);
  assert.deepEqual(parse('x,y', { header: true }), []);
  const records = Object.freeze([Object.freeze(['v', 'extra']), Object.freeze([])]);
  const header = Object.freeze(['__proto__']);
  const options = Object.freeze({ header });
  const objects = toObjects(records, options);
  assert.deepEqual(Object.values(objects[0]), ['v']);
  assert.deepEqual(Object.values(objects[1]), ['']);
  assert.deepEqual(records, [['v', 'extra'], []]);
  assert.deepEqual(header, ['__proto__']);
  assert.deepEqual(toObjects(records, { header: [] }), [{}, {}]);
});

